import sys


MAGIC = {ord("o"), ord("O"), ord("0")}


def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    pos = 1
    answers = []

    for _ in range(t):
        n = int(data[pos])
        s = data[pos + 1]
        pos += 2

        first = -1
        last = -1
        for i, ch in enumerate(s):
            if ch in MAGIC:
                if first == -1:
                    first = i
                last = i

        answers.append("0" if first == -1 else str(last - first + 1))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

