def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    weights = list(map(int, input().split()))
    k = int(input())

    def feasible(cap):
        segments = 1
        current = 0
        for weight in weights:
            if current + weight <= cap:
                current += weight
            else:
                segments += 1
                current = weight
                if segments > k:
                    return False
        return True

    left = max(weights)
    right = sum(weights)
    while left < right:
        middle = (left + right) // 2
        if feasible(middle):
            right = middle
        else:
            left = middle + 1

    print(left)


if __name__ == "__main__":
    solve()

