import math
import sys
from decimal import Decimal, ROUND_HALF_UP


def format_two_digits(x):
    value = Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if value == 0:
        value = Decimal("0.00")
    return format(value, ".2f")


def solve():
    input = sys.stdin.buffer.readline
    first = input().split()
    if len(first) != 4:
        return
    batch_size, n, d, window = map(int, first)
    if batch_size < 1 or n < 1 or d < 1 or not (1 <= window <= n):
        print(0)
        return

    scale = math.sqrt(d)
    for batch_index in range(batch_size):
        q = [list(map(float, input().split())) for _ in range(n)]
        k = [list(map(float, input().split())) for _ in range(n)]
        v = [list(map(float, input().split())) for _ in range(n)]

        if batch_index:
            print()
        for i in range(n):
            left = max(0, i - window)
            right = min(n, i + window + 1)
            scores = []
            for j in range(left, right):
                dot = sum(q[i][t] * k[j][t] for t in range(d))
                scores.append(dot / scale)

            maximum = max(scores)
            exponentials = [math.exp(score - maximum) for score in scores]
            denominator = sum(exponentials)
            result = []
            for t in range(d):
                numerator = sum(
                    exponentials[j - left] * v[j][t]
                    for j in range(left, right)
                )
                result.append(numerator / denominator)
            print(" ".join(format_two_digits(x) for x in result))


if __name__ == "__main__":
    solve()

