import sys


def solve():
    input = sys.stdin.buffer.readline
    n, capacity = map(int, input().split())
    infinity = 10**30
    dp = [infinity] * (capacity + 1)
    dp[0] = 0

    for _ in range(n):
        c1, t1, c2, t2 = map(int, input().split())
        next_dp = [infinity] * (capacity + 1)
        for used, total_time in enumerate(dp):
            if total_time == infinity:
                continue
            if used + c1 <= capacity:
                next_dp[used + c1] = min(next_dp[used + c1], total_time + t1)
            if used + c2 <= capacity:
                next_dp[used + c2] = min(next_dp[used + c2], total_time + t2)
        dp = next_dp

    best_time = min(dp)
    best_cost = next(cost for cost, time in enumerate(dp) if time == best_time)
    print(best_time, best_cost, capacity - best_cost)


if __name__ == "__main__":
    solve()

