import sys
from collections import deque

input = sys.stdin.readline


def parse_cards(s):
    cards = []
    i = 0
    while i < len(s):
        if s[i] == "1":
            cards.append("10")
            i += 2
        else:
            cards.append(s[i])
            i += 1
    return cards


def play(cards):
    hands = [deque(cards[::2]), deque(cards[1::2])]
    table = []
    current = 0
    while hands[0] and hands[1]:
        card = hands[current].popleft()
        collected = False
        if card == "J" and table:
            table.append(card)
            while table:
                hands[current].append(table.pop())
            collected = True
        elif card != "J" and card in table:
            position = table.index(card)
            table.append(card)
            while len(table) > position:
                hands[current].append(table.pop())
            collected = True
        else:
            table.append(card)
        if not collected:
            current = 1 - current
    winner = 0 if hands[0] else 1
    return ("sanqiu", "xiran")[winner], list(hands[winner])


def solve():
    winner, hand = play(parse_cards(input().strip()))
    print(winner)
    print(" ".join(hand))


if __name__ == "__main__":
    solve()

